// Packs assets/sounds/*.mp3 (listed in assets/sounds/manifest.json) into js/sound-data.js.
//
// Why a JS bundle: the game is opened straight from file://, where browsers block
// fetch()/XHR of local files. A plain <script> with base64 strings loads everywhere,
// and the audio engine decodes it with decodeAudioData.
//
// Usage (from the project root):  node tools/build-sound-bundle.mjs
// To replace a sound: overwrite the .mp3 in assets/sounds (keep the name) and rebuild.
// Loops (cat 'bed') carry {samples, head}: the original length and the first 512 samples (x20000),
// used by the game to cut a sample-exact loop out of the decoded MP3 (see js/audio.js loopExact).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dir = path.join(root, 'assets', 'sounds');
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));

const lines = [];
let bytes = 0;
for (const m of manifest) {
  const file = path.join(dir, m.file);
  if (!fs.existsSync(file)) throw new Error('missing sound file: ' + m.file);
  const b64 = fs.readFileSync(file).toString('base64');
  bytes += b64.length;
  const loop = m.samples ? `, ${JSON.stringify({ samples: m.samples, head: m.head })}` : '';
  lines.push(`  [${JSON.stringify(m.id)}, ${JSON.stringify(m.cat)}, ${JSON.stringify(b64)}${loop}],`);
}
const out =
  '// GENERATED by tools/build-sound-bundle.mjs from assets/sounds/*.mp3. Do not edit by hand.\n' +
  '// Sources and licenses (all CC0): assets/sounds/CREDITS.md\n' +
  '(function (TM) {\n' +
  "  'use strict';\n" +
  "  TM.SOUND_BANK = { format: 'mp3', sounds: [\n" + lines.join('\n') + '\n  ] };\n' +
  '})(window.TM = window.TM || {});\n';
fs.writeFileSync(path.join(root, 'js', 'sound-data.js'), out);
console.log(`js/sound-data.js: ${manifest.length} sounds, ${(bytes / 1024).toFixed(0)} KB of base64`);
